import axios from 'axios'

export type ApiResponse<T = unknown> = {
  success?: boolean
  code?: number
  message?: string
  data?: T
  trace_id?: string
  price_cents?: number
  next_poll_after_ms?: number
}

const runtime = (window as typeof window & { __PLUGIN_STATION__?: { apiBase?: string } }).__PLUGIN_STATION__ ?? {}

const api = axios.create({
  baseURL: runtime.apiBase ?? '/api.php',
  timeout: 15000,
})

function debugSummarizePayload(payload: Record<string, unknown>) {
  const summary: Record<string, unknown> = {}
  for (const [key, value] of Object.entries(payload)) {
    if (key.toLowerCase().includes('password')) {
      summary[key] = '[hidden]'
      continue
    }
    summary[key] = value
  }
  return summary
}

export function throwApiError(payload: ApiResponse, fallback: string): never {
  const error = new Error(payload.message || fallback) as Error & {
    response?: { data?: ApiResponse }
  }
  error.response = { data: payload }
  throw error
}

export async function request<T = unknown>(
  action: string,
  method: 'get' | 'post' = 'get',
  payload: Record<string, unknown> = {},
) {
  const startedAt = Date.now()
  const debugPayload = debugSummarizePayload(payload)
  console.info('[PLUGIN-DEBUG] request:start', {
    action,
    method,
    payload: debugPayload,
    baseURL: api.defaults.baseURL,
    startedAt,
  })
  try {
    const response = method === 'get'
      ? await api.get<ApiResponse<T>>('', { params: { action, ...payload } })
      : await api.post<ApiResponse<T>>('', payload, { params: { action } })
    const data = response.data
    console.info('[PLUGIN-DEBUG] request:finish', {
      action,
      method,
      durationMs: Date.now() - startedAt,
      httpStatus: response.status,
      success: data?.success,
      code: data?.code,
      message: data?.message,
      itemCount: Array.isArray(data?.data) ? data.data.length : undefined,
      keys: data && typeof data === 'object' ? Object.keys(data) : [],
    })
    if (!data || data.success === false) {
      console.error('[PLUGIN-DEBUG] request:business-fail', {
        action,
        method,
        durationMs: Date.now() - startedAt,
        payload: debugPayload,
        response: data,
      })
      throwApiError(data || {}, `${action} 请求失败`)
    }
    return data
  } catch (error) {
    console.error('[PLUGIN-DEBUG] request:error', {
      action,
      method,
      durationMs: Date.now() - startedAt,
      payload: debugPayload,
      message: axios.isAxiosError(error)
        ? error.response?.data?.message || error.message
        : error instanceof Error
          ? error.message
          : String(error),
      response: axios.isAxiosError(error) ? error.response?.data : undefined,
    })
    throw error
  }
}

export function getErrorMessage(error: unknown, fallback: string) {
  if (axios.isAxiosError(error)) {
    return error.response?.data?.message || fallback
  }
  if (error instanceof Error) {
    const responseMessage = (error as Error & { response?: { data?: ApiResponse } }).response?.data?.message
    return responseMessage || error.message || fallback
  }
  return fallback
}
